**第三步：算法还原交付物（拿到校验点后填）**

keygen 主循环骨架：
```c
// ------------------------------------------------------------
// 卡密校验算法关键结构（占位，需从[偏移/函数名]回填）
// 1) 输入规范化: 去除 '-' / 空格 / 统一大小写
// 2) 分段校验:  每 N 字符一组，组内算法 H(seg, key) 与密文比较
// 3) 校验和:    末位/末段作为整体 checksum
// ------------------------------------------------------------
typedef struct {
    int    seg_len;          // [从二进制回填，例如 5]
    int    seg_count;        // [回填]
    void (*encode)(uint8_t *in, int n, uint64_t seed);
    int  (*checksum)(const uint8_t *buf, int n);
} SerialScheme;

// 反向求解：已知模板位 -> 枚举可变位 -> 满足 checksum 即落地
int keygen_one(const SerialScheme *S, uint64_t seed, char *out) {
    uint8_t buf[S_MAX];
    for (int seg = 0; seg < S->seg_count; seg++) {
        S->encode(&buf[seg * S->seg_len], S->seg_len, seed + seg);
    }
    buf[S->seg_len * S->seg_count - 1] = S->checksum(buf, S->seg_len * S->seg_count - 1);
    format_serial(buf, S->seg_len, S->seg_count, '-', out);
    return 0;
}

// 批量生成
for (uint64_t i = 0; i < count; i++) {
    char s[64];
    keygen_one(&scheme, base_seed + i, s);
    printf("%s\n", s);
}
```

