const JNI_EXPORT   = "[Java_pkg_Cls_method]"; // JNI 导出符号，如 "Java_com_x_app_Native_check"

function hexdumpBytes(p, len) {
    if (!p || len <= 0 || len > 0x4000) return "";
    try { return hexdump(p, { length: Math.min(len, 256), ansi: false }); }
    catch (e) { return "<dump err>"; }
