function findExport() {
    const mod = Process.findModuleByName(MODULE_NAME);
    if (!mod) { console.log("[!] module not found: " + MODULE_NAME); return null; }
    console.log("[*] " + MODULE_NAME + " base=" + mod.base + " size=" + mod.size);
    const addr = mod.findExportByName(JNI_EXPORT);
    if (addr) console.log("[*] export " + JNI_EXPORT + " => " + addr);
    else      console.log("[!] export not found: " + JNI_EXPORT + " (要脱壳/去混淆后确认符号名)");
    return addr;
}

function hookJNIExport() {
    const addr = findExport();
    if (!addr) return;

    const isArm64 = Process.arch === "arm64";

    Interceptor.attach(addr, {
        onEnter(args) {
            this.env  = args[0];   // JNIEnv*
            this.obj  = args[1];   // jclass / jobject
            this.a2   = args[2];   // 常见: jstring / jbyteArray / int
            this.a3   = args[3];

            console.log("\n==== " + JNI_EXPORT + " ENTER ====");
            console.log("JNIEnv*=" + this.env + " self=" + this.obj);

            // 若第 3 参数是 jstring，尝试取明文
            if (this.a2 && !isArm64 || true) {
                try {
                    const s = Java.vm.tryGetEnv().getStringUtfChars(this.a2, null);
                    if (s) console.log("arg2 as jstring: " + s.readUtf8String());
                } catch (e) { /* not a jstring */ }
            }
            // 若是 jbyteArray，打印长度与内容
            try {
                const env = Java.vm.getEnv();
                const len = env.getArrayLength(this.a2);
                if (len >= 0 && len < 0x10000) {
                    console.log("arg2 as array len=" + len);
                    const p = env.getByteArrayElements ? null : null;
                }
            } catch (e) {}
        },
        onLeave(retval) {
            console.log("---- " + JNI_EXPORT + " RET=" + retval + " (" +
                        (retval.toInt32 ? retval.toInt32() : retval) + ")");
            console.log("==== EXIT ====\n");
        }
    });
}

// ---------- 通用兜底：导出名不确定时，按 so 内所有导出扫描 ----------
function hookAllExportsByKeyword(keyword) {
    const mod = Process.findModuleByName(MODULE_NAME);
    if (!mod) return;
    mod.enumerateExports().forEach(e => {
        if (e.name.indexOf(keyword) >= 0) {
            console.log("[*] hooking " + e.name + " @" + e.address);
            Interceptor.attach(e.address, {
                onEnter(args) {
                    this.n = e.name;
                    this.args = [args[0], args[1], args[2], args[3]];
                },
                onLeave(ret) {
                    console.log("  " + this.n + " ret=" + ret);
                }
            });
        }
    });
}

