// drv_rw.c — WDM 内核读写骨架（WDK 10.0.22621 编译）
#include <ntifs.h>
#include <ntddk.h>

#define DRV_TAG 'wRvD'
#define IOCTL_READ   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQ {
    ULONG  Pid;
    ULONG  Pad;
    ULONGLONG Addr;
    ULONG  Size;
    UCHAR  Data[1];
} RW_REQ, *PRW_REQ;

static NTSTATUS ReadProcMem(ULONG pid, ULONGLONG addr, PVOID buf, ULONG size)
{
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    SIZE_T done = 0;
    st = MmCopyVirtualMemory(proc, (PVOID)addr, PsGetCurrentProcess(), buf, size, KernelMode, &done);
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS WriteProcMem(ULONG pid, ULONGLONG addr, PVOID buf, ULONG size)
{
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    SIZE_T done = 0;
    st = MmCopyVirtualMemory(PsGetCurrentProcess(), buf, proc, (PVOID)addr, size, KernelMode, &done);
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS DrvDispatch(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION irpSp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;

    if (irpSp->Parameters.DeviceIoControl.IoControlCode == IOCTL_READ) {
        PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;
        if (req && irpSp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(RW_REQ)) {
            st = ReadProcMem(req->Pid, req->Addr, req->Data, req->Size);
            irp->IoStatus.Information = sizeof(RW_REQ) + req->Size;
        }
    } else if (irpSp->Parameters.DeviceIoControl.IoControlCode == IOCTL_WRITE) {
        PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;
        if (req && irpSp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(RW_REQ)) {
            st = WriteProcMem(req->Pid, req->Addr, req->Data, req->Size);
        }
    }

    irp->IoStatus.Status = st;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

