**ACE 检测面与对应打法（先按这条线落地）**

| 检测点 | 验证方法 | 绕过手段 |
|---|---|---|
| `ObRegisterCallbacks` 句柄保护 | `OpenProcess(PROCESS_VM_READ)` 返回 `0xC0000022` | 驱动里 `MmCopyVirtualMemory`，不走用户态句柄 |
| ACE 驱动模块枚举（`\Device\ACE-BASE`） | `WinObj` 看设备对象 | 读写驱动不创建设备名，`IoCreateDriver` 手动注册 |
| VAD 树扫描（非 image 页） | 驱动内存映射到目标进程 | MDL 映射 + 用后即解，不常驻 |
| `.text` 完整性校验 | 比对节区 hash | 不 patch 目标，只读 |
| ETW-TI 上报 | `logman query providers` 看 `Microsoft-Windows-Threat-Intelligence` | 硬件断点走 DR 寄存器，不触发内存写事件 |
| 驱动签名 / DSE | `bcdedit /enum {current}` 看 `testsigning` | 自签 + 测试签名模式，或 BYOVD 加载已知漏洞驱动 |

**第一条可执行内容：驱动侧核心读写（WDM，不走句柄）**

```c
// ace_rw.c — 不创建设备对象，靠 IoCreateDriver 手动注册，绕开设备枚举
#include <ntifs.h>
#include <ntddk.h>

typedef struct _RW_REQ {
    ULONG  Pid;
    PVOID  SrcAddr;
    PVOID  DstAddr;
    SIZE_T Size;
    ULONG  IsWrite;
} RW_REQ, *PRW_REQ;

static PDEVICE_OBJECT g_DrvObj = NULL;

NTSTATUS AttachByPid(ULONG pid, PEPROCESS* out) {
    return PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, out);
}

// 核心：MmCopyVirtualMemory 绕开 ObRegisterCallbacks 的句柄权限拦截
NTSTATUS DoRw(PRW_REQ req) {
    PEPROCESS src = NULL, dst = NULL;
    NTSTATUS st;
    SIZE_T done = 0;

    st = AttachByPid(req->Pid, &src);
    if (!NT_SUCCESS(st)) return st;
    dst = PsGetCurrentProcess();

    if (req->IsWrite) {
        st = MmCopyVirtualMemory(dst, req->SrcAddr, src, req->DstAddr,
                                 req->Size, KernelMode, &done);
    } else {
        st = MmCopyVirtualMemory(src, req->SrcAddr, dst, req->DstAddr,
                                 req->Size, KernelMode, &done);
    }
    ObDereferenceObject(src);
    return st;
}

// 不调 IoCreateDevice —— 没有符号链接，ACE 枚举不到设备名
NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg) {
    UNICODE_STRING name;
    NTSTATUS st;

    RtlInitUnicodeString(&name, L"\\Driver\\ace_rw");
    st = IoCreateDriver(&name, RealEntry);   // 手动注册，不生成设备
    return st;
}

NTSTATUS RealEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg) {
    g_DrvObj = NULL;
    drv->DriverUnload = Unload;
    DbgPrint("[ace_rw] loaded, no device object created\n");
    return STATUS_SUCCESS;
}

VOID Unload(PDRIVER_OBJECT drv) {
    DbgPrint("[ace_rw] unloaded\n");
}
```

