先给一段**摘 `PsLoadedModuleList` 链**的标准实现，贴代码时对照着看你的驱动缺哪块：

```c
// 从 PsLoadedModuleList 摘除当前驱动模块
// 注意：Win10 1809+ 该链表有完整性校验，需同时处理 DriverSection->FullDllName
NTSTATUS HideDriverModule()
{
    PLDR_DATA_TABLE_ENTRY entry = (PLDR_DATA_TABLE_ENTRY)DriverObject->DriverSection;
    if (!entry) return STATUS_UNSUCCESSFUL;

    // 1. 从 PsLoadedModuleList 双向链表摘除
    PLIST_ENTRY prev = entry->InLoadOrderLinks.Blink;
    PLIST_ENTRY next = entry->InLoadOrderLinks.Flink;
    prev->Flink = next;
    next->Blink = prev;

    // 2. 清空自身链接，防止被反向遍历找到
    entry->InLoadOrderLinks.Flink = &entry->InLoadOrderLinks;
    entry->InLoadOrderLinks.Blink = &entry->InLoadOrderLinks;

    // 3. 从内存顺序链表摘除（部分反作弊查这个）
    prev = entry->InMemoryOrderLinks.Blink;
    next = entry->InMemoryOrderLinks.Flink;
    prev->Flink = next;
    next->Blink = prev;

    return STATUS_SUCCESS;
}
```

