function ranges() {
  const out = [];
  const maps = File.readAllText('/proc/self/maps').split('\n');
  for (const l of maps) {
    const p = l.split(/\s+/);
    if (p.length < 2 || p[0].indexOf('-') < 0) continue;
    if (!/rw/.test(p[1])) continue;                 // 只要可写段
    if (/libc|libart|linker|\[/.test(p[5]||'')) continue;
    const [s, e] = p[0].split('-').map(x => parseInt(x, 16));
    out.push({ base: s, size: e - s });
  }
  return out;
}

// 例：金币当前 12345，扩大搜索窗口找 int32
const target = 12345;
