    const mem = Memory.readByteArray(r.base, r.size);
    const dv = new DataView(mem);
    for (let o = 0; o + 4 <= r.size; o += 4) {
      if (dv.getInt32(o, true) === target) hits.push(r.base.add(o));
    }
  } catch (e) {}
}
console.log('hits', hits.length, hits.slice(0, 20).map(String));
// 命中多就花/买一次变值后再扫，逐步收窄到唯一地址
