#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

int main(int argc, char** argv) {
    DWORD pid = argc > 1 ? atoi(argv[1]) : GetCurrentProcessId();
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { .dwSize = sizeof(pe) };
    for (BOOL ok = Process32First(snap, &pe); ok; ok = Process32Next(snap, &pe))
        if (pe.th32ProcessID == pid) printf("[PROC] visible: %ws pid=%lu\n", pe.szExeFile, pid);
    CloseHandle(snap);

    HANDLE h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    printf("[HANDLE] OpenProcess => %p (err=%lu)\n", h, GetLastError());
    if (h) CloseHandle(h);
    return 0;
}
