#define PEB_ImagePathName  0x60   // RTL_USER_PROCESS_PARAMETERS
#define PEB_CommandLine    0x70
#define PEB_ProcessParams  0x20   // PEB->ProcessParameters
// 改法：拿到 RTL_USER_PROCESS_PARAMETERS*，把 ImagePathName.Buffer 原地覆写成你想要的路径（长度保持不变）
