```c
OB_PREOP_CALLBACK_STATUS PreProc(PVOID ctx, POB_PRE_OPERATION_INFORMATION info) {
    if (info->KernelHandle) return OB_PREOP_SUCCESS;
    ACCESS_MASK strip = PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION;
    info->Parameters->CreateHandleInformation.DesiredAccess &= ~strip;
    info->Parameters->CreateHandleInformation.OriginalDesiredAccess &= ~strip;
    return OB_PREOP_SUCCESS;
}
// 注册：OB_OPERATION_REGISTRATION op = { PsProcessType, OB_OPERATION_HANDLE_CREATE|OB_OPERATION_HANDLE_DUPLICATE, PreProc, NULL };
```
