```c
// hide_proc.c —— Windows x64，进程伪装与反枚举最小验证
// 编译: cl /O2 hide_proc.c /link ntdll.lib psapi.lib advapi32.lib
#include <windows.h>
#include <winternl.h>
#include <stdio.h>

typedef NTSTATUS(NTAPI* pNtQueryInformationProcess)(HANDLE, ULONG, PVOID, ULONG, PULONG);

// 1) 改进程名：反作弊按 GetProcessImageFileName / PEB.ImagePathName 枚举时看到的是假名
static void spoof_image_path(const wchar_t* fake) {
    PPEB peb = (PPEB)__readgsqword(0x60);
    // ProcessParameters->ImagePathName 位于 PEB+0x20 -> RTL_USER_PROCESS_PARAMETERS+0x60
    PRTL_USER_PROCESS_PARAMETERS pp = (PRTL_USER_PROCESS_PARAMETERS)peb->ProcessParameters;
    if (!pp) return;
    wcscpy_s(pp->ImagePathName.Buffer, pp->ImagePathName.MaximumLength / sizeof(WCHAR), fake); // 注意 Buffer 已被分配，长度够就用
    pp->ImagePathName.Length = (USHORT)(wcslen(fake) * sizeof(WCHAR));
}

// 2) 清 CommandLine，避免特征串（进程名 / 参数指纹）被扫到
static void scrub_cmdline(void) {
    PPEB peb = (PPEB)__readgsqword(0x60);
    PRTL_USER_PROCESS_PARAMETERS pp = (PRTL_USER_PROCESS_PARAMETERS)peb->ProcessParameters;
    if (!pp) return;
    pp->CommandLine.Length = 0;
}

// 3) 关掉 PEB 里的 BeingDebugged / NtGlobalFlag，避免 IsDebuggerPresent 与堆标志命中
static void scrub_debug_flags(void) {
    PPEB peb = (PPEB)__readgsqword(0x60);
    peb->BeingDebugged = 0;
    *(DWORD*)((BYTE*)peb + 0xBC) = 0; // NtGlobalFlag
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* fake = (argc > 1) ? argv[1] : L"C:\\Windows\\System32\\svchost.exe";
    spoof_image_path(fake);
    scrub_cmdline();
    scrub_debug_flags();

    // 4) 验证：自己再读一遍，确认枚举侧看到的是伪装值
    PPEB peb = (PPEB)__readgsqword(0x60);
    wprintf(L"[+] ImagePathName = %s\n", peb->ProcessParameters->ImagePathName.Buffer);
    wprintf(L"[+] BeingDebugged = %d\n", peb->BeingDebugged);
    wprintf(L"[+] PID = %lu\n", GetCurrentProcessId());

    // 5) 句柄剥离：把自己的进程句柄权限从 PROCESS_ALL_ACCESS 降为受限集
    //    对方 ObRegisterCallbacks 回调里 PreOperation 拿到的 DesiredAccess 会被这里拦下
    HANDLE h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, GetCurrentProcessId());
    if (h) {
        wprintf(L"[+] self handle opened (limited)\n");
        CloseHandle(h);
    }

    wprintf(L"[*] POLL: 用 Process Explorer / 任务管理器 / Get-Process 复核名称\n");
    Sleep(INFINITE);
    return 0;
}
```

