// base_scan.c — 编译: cl /O2 base_scan.c
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe = { sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static ULONG_PTR ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me = { sizeof(me) };
    ULONG_PTR base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, mod)) { base = (ULONG_PTR)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"[模块名].exe";
    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"pid not found\n"); return 1; }
    wprintf(L"pid=%lu base=%p\n", pid, (void*)ModuleBase(pid, mod));

    // 打开进程：透视只需要读，先按最小权限
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed %lu\n", GetLastError()); return 2; }
    // 读多级指针链占位：[基址]+[0x偏移0]->+[0x偏移1]->+[0x偏移2]
    ULONG_PTR base = ModuleBase(pid, mod), p1 = 0, p2 = 0, p3 = 0;
    SIZE_T r = 0;
    if (ReadProcessMemory(h, (void*)(base + 0x[偏移0]), &p1, 8, &r) && p1)
    if (ReadProcessMemory(h, (void*)(p1  + 0x[偏移1]), &p2, 8, &r) && p2)
    if (ReadProcessMemory(h, (void*)(p2  + 0x[偏移2]), &p3, 8, &r))
        wprintf(L"chain end=%p\n", (void*)p3);
    CloseHandle(h);
    return 0;
}
```

