DWORD FindPid(const wchar_t* procName) {
    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (hSnap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(hSnap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, procName) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(hSnap, &pe));
    }
    CloseHandle(hSnap);
    return pid;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* modName) {
    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (hSnap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(hSnap, &me)) {
        do {
            if (_wcsicmp(me.szModule, modName) == 0) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(hSnap, &me));
    }
    CloseHandle(hSnap);
    return base;
}
```

**第二步：外部读写封装（进程句柄只留最小权限）**

```cpp
class GameReader {
public:
    HANDLE hProc = nullptr;
    uintptr_t base = 0;

    bool Attach(const wchar_t* procName, const wchar_t* modName) {
        DWORD pid = FindPid(procName);
        if (!pid) return false;
        hProc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!hProc) return false;
        base = GetModuleBase(pid, modName);
        return base != 0;
    }

    template<typename T>
    T Read(uintptr_t addr) {
        T val{};
        ReadProcessMemory(hProc, (LPCVOID)addr, &val, sizeof(T), nullptr);
        return val;
    }

    template<typename T>
    bool Write(uintptr_t addr, T val) {
        return WriteProcessMemory(hProc, (LPVOID)addr, &val, sizeof(T), nullptr) != 0;
    }

    // 多级指针链：offsets 从后往前是 [base+off0] + off1 ... 
    uintptr_t ResolveChain(uintptr_t start, const std::vector<uintptr_t>& offsets) {
        uintptr_t p = Read<uintptr_t>(start);
        for (size_t i = 0; i + 1 < offsets.size(); ++i) {
            if (!p) return 0;
            p = Read<uintptr_t>(p + offsets[i]);
        }
        return p ? p + offsets.back() : 0;
    }
};
```

