// kmemdrv.c
#include <ntifs.h>
#include <ntddk.h>

#define DEVICE_NAME     L"\\Device\\KmDrv"
#define SYMLINK_NAME    L"\\DosDevices\\KmDrv"

typedef struct _RW_REQUEST {
    ULONG   pid;
    ULONG64 srcAddr;
    ULONG64 dstAddr;
    ULONG64 size;
    ULONG   isWrite;   // 0=read, 1=write
} RW_REQUEST, *PRW_REQUEST;

#define IOCTL_RW CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)

static NTSTATUS CopyMemByPid(ULONG pid, PVOID src, PVOID dst, SIZE_T size, BOOLEAN isWrite)
{
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    KAPC_STATE apc;
    KeStackAttachProcess(proc, &apc);

    SIZE_T copied = 0;
    PVOID  target = isWrite ? src : dst;   // 目标进程地址
    PVOID  caller = isWrite ? dst : src;   // 驱动侧缓冲

    if (isWrite) {
        st = MmCopyVirtualMemory(PsGetCurrentProcess(), caller, proc, target, size,
                                 KernelMode, &copied);
    } else {
        st = MmCopyVirtualMemory(proc, target, PsGetCurrentProcess(), caller, size,
                                 KernelMode, &copied);
    }

    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS DispatchIoCtrl(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_PARAMETER;
    ULONG outLen = 0;

    ULONG inLen = sp->Parameters.DeviceIoControl.InputBufferLength;
    ULONG code  = sp->Parameters.DeviceIoControl.IoControlCode;

    if (code == IOCTL_RW && inLen >= sizeof(RW_REQUEST)) {
        PRW_REQUEST req = (PRW_REQUEST)irp->AssociatedIrp.SystemBuffer;
        if (req->size <= 0x10000000) {
            st = CopyMemByPid(req->pid,
                              (PVOID)(ULONG_PTR)req->srcAddr,
                              (PVOID)(ULONG_PTR)req->dstAddr,
                              (SIZE_T)req->size,
                              req->isWrite ? TRUE : FALSE);
            outLen = sizeof(RW_REQUEST);
        }
    }

    irp->IoStatus.Status = st;
    irp->IoStatus.Information = outLen;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

static NTSTATUS DispatchCreate(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    UNREFERENCED_PARAMETER(reg);
    PDEVICE_OBJECT dev = NULL;
    UNICODE_STRING devName, symName;

    RtlInitUnicodeString(&devName, DEVICE_NAME);
    RtlInitUnicodeString(&symName, SYMLINK_NAME);

    NTSTATUS st = IoCreateDevice(drv, 0, &devName, FILE_DEVICE_UNKNOWN,
                                 FILE_DEVICE_SECURE_OPEN, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;

    IoCreateSymbolicLink(&symName, &devName);

    drv->MajorFunction[IRP_MJ_CREATE]         = DispatchCreate;
    drv->MajorFunction[IRP_MJ_CLOSE]          = DispatchCreate;
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = DispatchIoCtrl;

    return STATUS_SUCCESS;
}
```

