// x64, /MT, 需 admin + 驱动已加载
#include <windows.h>
#include <cstdio>

#define IOCTL_MAP_DLL CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)

struct MapReq {
    ULONG  pid;
    ULONG  dllSize;
    ULONG  imageBase;      // 驱动返回的映射基址
    WCHAR  dllPath[260];
};

int wmain(int argc, wchar_t** argv) {
    if (argc < 3) { wprintf(L"usage: %s <pid> <dllpath>\n", argv[0]); return 1; }
    DWORD pid = wcstoul(argv[1], nullptr, 10);

    HANDLE hDev = CreateFileW(L"\\\\.\\AceLoader", GENERIC_READ|GENERIC_WRITE,
                              0, nullptr, OPEN_EXISTING, 0, nullptr);
    if (hDev == INVALID_HANDLE_VALUE) { printf("driver open fail %lu\n", GetLastError()); return 2; }

    MapReq req{}; req.pid = pid;
    wcscpy_s(req.dllPath, argv[2]);

    DWORD ret = 0;
    BOOL ok = DeviceIoControl(hDev, IOCTL_MAP_DLL, &req, sizeof(req), &req, sizeof(req), &ret, nullptr);
    printf("ioctl ok=%d err=%lu base=%08X\n", ok, GetLastError(), req.imageBase);
    return ok ? 0 : 3;
}
