// ---------- ntdll 原生函数 ----------
using NtAllocateVirtualMemory_t = NTSTATUS(NTAPI*)(HANDLE, PVOID*, ULONG_PTR, PSIZE_T, ULONG, ULONG);
using NtWriteVirtualMemory_t    = NTSTATUS(NTAPI*)(HANDLE, PVOID, PVOID, SIZE_T, PSIZE_T);
using NtProtectVirtualMemory_t  = NTSTATUS(NTAPI*)(HANDLE, PVOID*, PSIZE_T, ULONG, PULONG);
using NtCreateThreadEx_t        = NTSTATUS(NTAPI*)(PHANDLE, ACCESS_MASK, PVOID, HANDLE, PVOID, PVOID, ULONG, SIZE_T, SIZE_T, SIZE_T, PVOID);
using NtFlushInstructionCache_t = NTSTATUS(NTAPI*)(HANDLE, PVOID, SIZE_T);

struct NtApi {
    NtAllocateVirtualMemory_t Alloc;
    NtWriteVirtualMemory_t    Write;
    NtProtectVirtualMemory_t  Protect;
    NtCreateThreadEx_t        CreateThreadEx;
    NtFlushInstructionCache_t Flush;
} nt;

static bool ResolveNt() {
    HMODULE n = GetModuleHandleW(L"ntdll.dll");
    if (!n) return false;
    nt.Alloc        = (NtAllocateVirtualMemory_t)GetProcAddress(n, "NtAllocateVirtualMemory");
    nt.Write        = (NtWriteVirtualMemory_t)GetProcAddress(n, "NtWriteVirtualMemory");
    nt.Protect      = (NtProtectVirtualMemory_t)GetProcAddress(n, "NtProtectVirtualMemory");
    nt.CreateThreadEx = (NtCreateThreadEx_t)GetProcAddress(n, "NtCreateThreadEx");
    nt.Flush        = (NtFlushInstructionCache_t)GetProcAddress(n, "NtFlushInstructionCache");
    return nt.Alloc && nt.Write && nt.Protect && nt.CreateThreadEx && nt.Flush;
}

// ---------- 工具 ----------
static DWORD FindPid(const wchar_t* name) {
    HANDLE s = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (s == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(s, &pe)) {
        do { if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; } } while (Process32NextW(s, &pe));
    }
    CloseHandle(s);
    return pid;
}

static std::vector<BYTE> ReadFileBytes(const char* path) {
    HANDLE f = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, 0, nullptr);
    if (f == INVALID_HANDLE_VALUE) return {};
    LARGE_INTEGER sz{}; GetFileSizeEx(f, &sz);
    std::vector<BYTE> buf((size_t)sz.QuadPart);
    DWORD rd = 0; ReadFile(f, buf.data(), (DWORD)buf.size(), &rd, nullptr);
    CloseHandle(f); buf.resize(rd); return buf;
}

static PBYTE RemoteAlloc(HANDLE h, SIZE_T size, ULONG prot) {
    PVOID p = nullptr; SIZE_T s = size;
    if (nt.Alloc(h, &p, 0, &s, MEM_COMMIT | MEM_RESERVE, prot) != 0) return nullptr;
    return (PBYTE)p;
}
static bool RemoteWrite(HANDLE h, PVOID dst, const void* src, SIZE_T n) {
    SIZE_T w = 0;
    return nt.Write(h, dst, (PVOID)src, n, &w) == 0 && w == n;
}
static bool RemoteProt(HANDLE h, PVOID addr, SIZE_T n, ULONG prot, PULONG old = nullptr) {
    PVOID a = addr; SIZE_T s = n; ULONG o = 0;
    return nt.Protect(h, &a, &s, prot, old ? old : &o) == 0;
