## 2. 物理内存读写原语（不依赖任何 API 附加进程）

### 2.1 物理地址 → 虚拟地址映射（`MmMapIoSpaceEx` 路线）

```c
// 单次映射一段物理页到内核虚拟地址，读写完立即 unmap
static PVOID g_PhysMapBase = NULL;
static PHYSICAL_ADDRESS g_PhysMapPa = { 0 };
static SIZE_T g_PhysMapSize = 0;

NTSTATUS PhysMap(PHYSICAL_ADDRESS pa, SIZE_T size)
{
    PhysUnmap();
    if (size > 0x400000) size = 0x400000;      // 最多 4MB 一段
    pa.QuadPart &= ~0xFFFULL;
    g_PhysMapSize = ROUND_TO_PAGES(size);
    g_PhysMapPa   = pa;
    g_PhysMapBase = MmMapIoSpaceEx(pa, g_PhysMapSize, PAGE_READWRITE | PAGE_NOCACHE);
    return g_PhysMapBase ? STATUS_SUCCESS : STATUS_UNSUCCESSFUL;
}

VOID PhysUnmap(VOID)
{
    if (g_PhysMapBase) {
        MmUnmapIoSpace(g_PhysMapBase, g_PhysMapSize);
        g_PhysMapBase = NULL;
    }
}

// 物理地址读/写（跨映射段时自动分段）
BOOLEAN PhysRead(PHYSICAL_ADDRESS pa, PVOID buf, SIZE_T len)
{
    PUCHAR out = (PUCHAR)buf;
    while (len) {
        SIZE_T offInPage = pa.QuadPart & 0xFFF;
        SIZE_T chunk = min(len, 0x400000 - offInPage);
        if (!g_PhysMapBase || pa.QuadPart < g_PhysMapPa.QuadPart ||
            (pa.QuadPart - g_PhysMapPa.QuadPart) + chunk > g_PhysMapSize) {
            if (!NT_SUCCESS(PhysMap(pa, chunk))) return FALSE;
            offInPage = pa.QuadPart - g_PhysMapPa.QuadPart;
        }
        RtlCopyMemory(out, (PUCHAR)g_PhysMapBase + offInPage, chunk);
        out += chunk; pa.QuadPart += chunk; len -= chunk;
    }
    return TRUE;
}

