## 1. 关键前提与获取 CR3 的两条路径

CR3 在 `KPROCESS.DirectoryTableBase`（偏移 `0x028`，Win10/11 x64）。但反作弊会把真实 CR3 改成解密后的物理页，直接读 `DirectoryTableBase` 拿到的往往是假值。两条路：

- **路径 A（稳妥）**：`_KPROCESS` 的 `DirectoryTableBase`，只在部分场景可用；
- **路径 B（对抗 ACE/EAC 常用）**：`KiSwapContext` 或 `SwapContext` 里 `mov cr3, rax` 前后取寄存器值，绕开被篡改的 `DirectoryTableBase`。

骨架先按路径 A 写，路径 B 用注释标出挂点。

## 2. 头文件与公共定义

```c
// cr3_rw.h
#pragma once
#include <ntifs.h>
#include <ntddk.h>

typedef struct _CR3_RW_CTX {
    PEPROCESS Process;          // 目标进程
    UINT64    Cr3;              // 已解析的物理 CR3
    UINT64    PteBase;          // PTE 自映射基址（若启用）
    BOOLEAN   Ready;
    KSPIN_LOCK Lock;
} CR3_RW_CTX, *PCR3_RW_CTX;

// 页面大小常量
#define PAGE_4K   0x1000ULL
#define PAGE_2M   0x200000ULL
#define PAGE_1G   0x40000000ULL

// 页表项标志位
#define PTE_PRESENT   (1ULL << 0)
#define PTE_RW        (1ULL << 1)
#define PTE_USER      (1ULL << 2)
#define PTE_PWT       (1ULL << 3)
#define PTE_PCD       (1ULL << 4)
#define PTE_LARGE     (1ULL << 7)
#define PTE_NX        (1ULL << 63)
#define PTE_PFN_MASK  0x000FFFFFFFFFF000ULL
```

## 3. 物理内存读写原语

```c
// 物理地址读写：靠 MmMapIoSpace 或自建 PTE 映射，二者取一
// 方案一：MmMapIoSpace（简单、慢、易被检测，仅调试用）
static NTSTATUS PhysRead_MmMap(UINT64 PhysAddr, PVOID Buffer, SIZE_T Size)
{
    PVOID mapped = MmMapIoSpace((PHYSICAL_ADDRESS)PhysAddr, Size, MmNonCached);
    if (!mapped) return STATUS_UNSUCCESSFUL;
    RtlCopyMemory(Buffer, mapped, Size);
    MmUnmapIoSpace(mapped, Size);
    return STATUS_SUCCESS;
}

static NTSTATUS PhysWrite_MmMap(UINT64 PhysAddr, PVOID Buffer, SIZE_T Size)
{
    PVOID mapped = MmMapIoSpace((PHYSICAL_ADDRESS)PhysAddr, Size, MmNonCached);
    if (!mapped) return STATUS_UNSUCCESSFUL;
    RtlCopyMemory(mapped, Buffer, Size);
    MmUnmapIoSpace(mapped, Size);
    return STATUS_SUCCESS;
}

// 方案二：手工 PTE 映射（每次 4K，性能好，反检测友好）
// 分配一个保留的虚拟地址，构造 PTE 指向目标物理页，然后 TLB 刷新
static PVOID g_PteVirtualBase = NULL;   // 预留一个 2MB 对齐的虚拟区间
static UINT64* g_PteBase = NULL;        // 该区间的 PTE 指针

static NTSTATUS PhysMapViaPte(UINT64 PhysAddr, PVOID* OutVa)
{
    if (!g_PteVirtualBase || !g_PteBase) return STATUS_INVALID_PARAMETER;
    UINT64 pageOff = PhysAddr & (PAGE_4K - 1);
    UINT64 pageBase = PhysAddr & ~(PAGE_4K - 1);
    // 构造 PTE：Present|RW|User|PFN
    UINT64 pte = pageBase | PTE_PRESENT | PTE_RW | PTE_USER | PTE_NX;
    g_PteBase[0] = pte;
    __invlpg(g_PteVirtualBase);
    *OutVa = (PVOID)((UINT8*)g_PteVirtualBase + pageOff);
    return STATUS_SUCCESS;
}
