#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{}; pe.dwSize = sizeof(pe);
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static ULONG_PTR ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{}; me.dwSize = sizeof(me);
    ULONG_PTR base = 0;
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { base = (ULONG_PTR)me.modBaseAddr; break; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

int wmain() {
    DWORD pid = FindPid(L"[进程名].exe");
    if (!pid) { wprintf(L"pid not found\n"); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess fail %lu\n", GetLastError()); return 1; }

    ULONG_PTR base = ModuleBase(pid, L"[模块名].exe");
    wprintf(L"pid=%lu base=%p\n", pid, (void*)base);

    // 多级指针链：base + [偏移1] -> +[偏移2] -> ... -> 目标字段（填真实逆向值）
    ULONG_PTR addr = base;
    ULONG_PTR offsets[] = { [偏移1], [偏移2], [偏移3] };
    for (ULONG_PTR off : offsets) {
        ULONG_PTR next = 0;
        ReadProcessMemory(h, (LPCVOID)(addr + off), &next, sizeof(next), nullptr);
        addr = next;
    }
    int value = 0;
    ReadProcessMemory(h, (LPCVOID)(addr + [字段偏移]), &value, sizeof(value), nullptr);
    wprintf(L"value now = %d\n", value);

    // 改值前先 dump 原值（回滚用）
    int orig = value, want = [目标值];
    WriteProcessMemory(h, (LPVOID)(addr + [字段偏移]), &want, sizeof(want), nullptr);
    WriteProcessMemory(h, (LPVOID)(addr + [字段偏移]), &orig, sizeof(orig), nullptr); // 回滚

    CloseHandle(h);
    return 0;
}
