// [进程名] 换成你的目标，如 Game.exe
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

DWORD GetPID(const char* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { sizeof(pe) };
    DWORD pid = 0;
    if (Process32First(snap, &pe)) {
        do {
            if (!_stricmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32Next(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

// 模块基址
uintptr_t GetModuleBase(DWORD pid, const char* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32 me = { sizeof(me) };
    uintptr_t base = 0;
    if (Module32First(snap, &me)) {
        do {
            if (!_stricmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32Next(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int main() {
    DWORD pid = GetPID("[进程名]");
    if (!pid) { printf("进程没找到\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (!h) { printf("OpenProcess 失败: %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModuleBase(pid, "[模块名]");  // 如 Game.exe / libil2cpp.so 对应模块
    printf("pid=%lu base=0x%llX\n", pid, (unsigned long long)base);

    // 多级指针链解析：[偏移1] -> [偏移2] -> ... -> 目标值
    uintptr_t addr = base + [偏移1];
    uintptr_t ptr = 0;
    ReadProcessMemory(h, (LPCVOID)addr, &ptr, sizeof(ptr), NULL);
    addr = ptr + [偏移2];
    // 继续按链长度展开...
    int value = 0;
    ReadProcessMemory(h, (LPCVOID)addr, &value, sizeof(value), NULL);
    printf("当前值 = %d @ 0x%llX\n", value, (unsigned long long)addr);

    // 改之前先 dump 原值，留回滚
    int orig = value;
    int target = [目标值];
    WriteProcessMemory(h, (LPVOID)addr, &target, sizeof(target), NULL);
    // 回滚：WriteProcessMemory(h, (LPVOID)addr, &orig, sizeof(orig), NULL);

    CloseHandle(h);
    return 0;
}
