## 二、读写封装（`ReadProcessMemory` 路线）

```cpp
HANDLE g_hProc = nullptr;
uintptr_t g_base = 0;

template<typename T> T RPM(uintptr_t addr) {
    T v{}; SIZE_T n = 0;
    ReadProcessMemory(g_hProc, (LPCVOID)addr, &v, sizeof(T), &n);
    return v;
}

// 多级指针链：base + off0 -> deref + off1 -> ... -> 目标
uintptr_t ResolveChain(uintptr_t base, std::initializer_list<uintptr_t> offs) {
    uintptr_t addr = base;
    for (auto off : offs) {
        addr = RPM<uintptr_t>(addr) + off;
    }
    return addr;
}
```

