### 1. 基础读写与模块基址

```cpp
// mem.h
#pragma once
#include <windows.h>
#include <TlHelp32.h>
#include <vector>
#include <string>

class Mem {
public:
    HANDLE h = nullptr;
    DWORD pid = 0;
    uintptr_t base = 0;
    size_t imgSize = 0;

    bool Attach(const wchar_t* procName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        PROCESSENTRY32W pe{ sizeof(pe) };
        if (Process32FirstW(snap, &pe)) do {
            if (!_wcsicmp(pe.szExeFile, procName)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
        CloseHandle(snap);
        if (!pid) return false;

        h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION |
                        PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!h) return false;

        HANDLE ms = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        MODULEENTRY32W me{ sizeof(me) };
        if (Module32FirstW(ms, &me)) do {
            if (!_wcsicmp(me.szModule, procName)) {
                base = (uintptr_t)me.modBaseAddr;
                imgSize = me.modBaseSize;
                break;
            }
        } while (Module32NextW(ms, &me));
        CloseHandle(ms);
        return base != 0;
    }

    template<typename T> T Read(uintptr_t addr) {
        T v{}; ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(T), nullptr); return v;
    }
    template<typename T> bool Write(uintptr_t addr, const T& v) {
        return WriteProcessMemory(h, (LPVOID)addr, &v, sizeof(T), nullptr);
    }
    bool ReadBuf(uintptr_t addr, void* buf, size_t sz) {
        return ReadProcessMemory(h, (LPCVOID)addr, buf, sz, nullptr);
    }
    uintptr_t Chain(uintptr_t p, const std::vector<uintptr_t>& offs) {
        for (size_t i = 0; i + 1 < offs.size(); i++) {
            p = Read<uintptr_t>(p + offs[i]);
            if (!p || p < 0x10000 || p > 0x7FFFFFFFFFFF) return 0;
        }
        return p + offs.back();
    }
};
```

